public static String convertDatesToWeekdays(String date) {
    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    String[] months = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
    String[] dateArray = date.split("\\s+");
    int month = Integer.parseInt(dateArray[0]);
    int day = Integer.parseInt(dateArray[1]);
    int year = Integer.parseInt(dateArray[2]);
    int dayOfWeek = calculateDayOfWeek(year, month, day);
    String weekday = weekdays[dayOfWeek];
    String monthName = months[month - 1];
    return monthName + " " + day + ", " + year + " is a " + weekday;
}

public static int calculateDayOfWeek(int year, int month, int day) {
    if (month < 3) {
        year--;
        month += 12;
    }
    int a = year % 100;
    int b = year / 100;
    int c = a / 4;
    int d = b / 4;
    int e = (8 * b + 13) / 25;
    int f = (13 - (month + 1)) / 12;
    int g = year + d + c - (15 * e) + 2 * year;
    int h = (11 * g) / 48;
    int i = h / 30;
    int j = (g - (31 * i) - (e + i + 1) + 5) % 7;
    return (j + 7) % 7;
}
